/**
 * CategoryList Component Tests
 *
 * Tests for the categories page list rendering, hierarchy display, and visibility logic.
 * This file tests the category list display, empty states, loading states,
 * error handling, and hierarchical category structure.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { render } from '@/__tests__/utils/test-utils'
import type { Category } from '@/types/database'
import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
import CategoriesPage from '../page'

// Mock the Supabase client
vi.mock('@/lib/supabase/client', () => ({
  createClient: vi.fn(),
}))

// Import after mocking to get the mocked version
import { createClient } from '@/lib/supabase/client'

describe('CategoryList', () => {
  const mockOrganizationId = 'test-org-id'

  // Helper function to create mock categories with correct type
  const createMockCategory = (overrides: Partial<Category> = {}): Category => {
    const now = new Date().toISOString()
    return {
      id: 'cat-' + Math.random().toString(36).substring(7),
      organization_id: 'org-test',
      name: 'Test Category',
      slug: 'test-category',
      sort_order: 0,
      parent_id: null,
      is_visible: true,
      created_at: now,
      ...overrides,
    }
  }

  beforeEach(() => {
    vi.clearAllMocks()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('Category List Rendering', () => {
    it('renders category list correctly with categories', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Ana Yemekler',
          slug: 'ana-yemekler',
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-2',
          name: 'Tatlilar',
          slug: 'tatlilar',
          sort_order: 1,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Ana Yemekler')).toBeInTheDocument()
      })

      expect(screen.getByText('Tatlilar')).toBeInTheDocument()
      expect(screen.getByText('/ana-yemekler')).toBeInTheDocument()
      expect(screen.getByText('/tatlilar')).toBeInTheDocument()
      expect(screen.getByText('#0')).toBeInTheDocument()
      expect(screen.getByText('#1')).toBeInTheDocument()
    })

    it('displays hierarchical category structure', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'parent-1',
          name: 'Parent Category',
          slug: 'parent-category',
          parent_id: null,
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'child-1',
          name: 'Child Category 1',
          slug: 'child-category-1',
          parent_id: 'parent-1',
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'child-2',
          name: 'Child Category 2',
          slug: 'child-category-2',
          parent_id: 'parent-1',
          sort_order: 1,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Parent Category')).toBeInTheDocument()
      })

      expect(screen.getByText('Child Category 1')).toBeInTheDocument()
      expect(screen.getByText('Child Category 2')).toBeInTheDocument()

      // Check that children are displayed after parent
      const parentElement = screen.getByText('Parent Category')
      const child1Element = screen.getByText('Child Category 1')
      const child2Element = screen.getByText('Child Category 2')

      expect(parentElement).toBeInTheDocument()
      expect(child1Element).toBeInTheDocument()
      expect(child2Element).toBeInTheDocument()
    })

    it('displays hidden categories with reduced opacity', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Hidden Category',
          slug: 'hidden-category',
          is_visible: false,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Hidden Category')).toBeInTheDocument()
      })

      // Find the parent container with opacity class
      const categoryElement = screen.getByText('Hidden Category').closest('div')
      expect(categoryElement?.className).toMatch(/opacity-60/)
    })

    it('displays category count correctly', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-1',
          name: 'Category 1',
          slug: 'category-1',
          sort_order: 0,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-2',
          name: 'Category 2',
          slug: 'category-2',
          sort_order: 1,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-3',
          name: 'Category 3',
          slug: 'category-3',
          sort_order: 2,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Toplam 3 kategori')).toBeInTheDocument()
      })
    })
  })

  describe('Empty State', () => {
    it('displays empty state when no categories exist', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: [] })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('Henuz kategori yok')).toBeInTheDocument()
      })

      expect(
        screen.getByText('Ilk kategorinizi olusturarak baslayin.')
      ).toBeInTheDocument()
    })
  })

  describe('Loading State', () => {
    it('shows loading spinner during data fetch', async () => {
      // Arrange
      let resolvePromise: (value: any) => void
      const delayedPromise = new Promise((resolve) => {
        resolvePromise = resolve
      })

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return delayedPromise.then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert - should show loading spinner
      const spinner = document.querySelector('.animate-spin')
      expect(spinner).toBeInTheDocument()

      // Resolve the promise
      resolvePromise!({ data: [], error: null })

      // Wait for loading to finish
      await waitFor(() => {
        expect(document.querySelector('.animate-spin')).not.toBeInTheDocument()
      })
    })
  })

  describe('Error Handling', () => {
    it('displays error message when fetch fails', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(
          screen.getByText('Kategoriler yuklenirken bir hata olustu.')
        ).toBeInTheDocument()
      })
    })

    it('allows dismissing error message', async () => {
      // Arrange
      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder()
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder() {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: null,
              error: { message: 'Database error' },
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      const user = userEvent.setup()

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      await waitFor(() => {
        expect(
          screen.getByText('Kategoriler yuklenirken bir hata olustu.')
        ).toBeInTheDocument()
      })

      // Click the close button
      const closeButton = screen.getByText('Kapat')
      await user.click(closeButton)

      // Assert
      await waitFor(() => {
        expect(
          screen.queryByText('Kategoriler yuklenirken bir hata olustu.')
        ).not.toBeInTheDocument()
      })
    })
  })

  describe('Hierarchy Display', () => {
    it('displays multi-level category hierarchy', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'grandparent',
          name: 'Grandparent',
          slug: 'grandparent',
          parent_id: null,
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'parent',
          name: 'Parent',
          slug: 'parent',
          parent_id: 'grandparent',
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'child',
          name: 'Child',
          slug: 'child',
          parent_id: 'parent',
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert - all levels should be displayed
      await waitFor(() => {
        expect(screen.getByText('Grandparent')).toBeInTheDocument()
      })

      expect(screen.getByText('Parent')).toBeInTheDocument()
      expect(screen.getByText('Child')).toBeInTheDocument()
    })

    it('orders categories by sort_order within each level', async () => {
      // Arrange
      const mockCategories = [
        createMockCategory({
          id: 'cat-3',
          name: 'Third Category',
          slug: 'third-category',
          parent_id: null,
          sort_order: 2,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-1',
          name: 'First Category',
          slug: 'first-category',
          parent_id: null,
          sort_order: 0,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
        createMockCategory({
          id: 'cat-2',
          name: 'Second Category',
          slug: 'second-category',
          parent_id: null,
          sort_order: 1,
          is_visible: true,
          organization_id: mockOrganizationId,
        }),
      ]

      const mockClient = createMockSupabaseClient()
      vi.mocked(createClient).mockReturnValue(mockClient as any)

      const fromMock = vi.fn(() => {
        return createMockQueryBuilder({ selectData: mockCategories })
      })

      mockClient.from = fromMock as any

      function createMockQueryBuilder(config: any) {
        const queryBuilder = {
          select: vi.fn(() => queryBuilder),
          eq: vi.fn(() => queryBuilder),
          order: vi.fn(() => queryBuilder),
          then: vi.fn((callback) => {
            return Promise.resolve({
              data: config.selectData,
              error: null,
            }).then(callback)
          }),
        }
        return queryBuilder
      }

      // Act
      render(<CategoriesPage />, {
        authContext: {
          organization: { id: mockOrganizationId } as any,
        },
      })

      // Assert
      await waitFor(() => {
        expect(screen.getByText('First Category')).toBeInTheDocument()
      })

      expect(screen.getByText('Second Category')).toBeInTheDocument()
      expect(screen.getByText('Third Category')).toBeInTheDocument()

      // Verify sort order badges
      expect(screen.getByText('#0')).toBeInTheDocument()
      expect(screen.getByText('#1')).toBeInTheDocument()
      expect(screen.getByText('#2')).toBeInTheDocument()
    })
  })
})
